"Урок 9. Мудрость народа": "9-дәрис. Хәлқниң даналиғи",
"Мудрость народа": "Хәлқниң даналиғи",
"Различать жырау и акынов, называть Жаяу Мусу и объяснять, о чём его песня «Ақ сиса».": "Жырау вә ақинларни пәриқләндүрүп, Жаяу Мусани атап, униң «Ақ сиса» нахшисиниң немә һәққидә екәнлигини чүшәндүрүш.",
"Песни во все времена отражали жизнь народа и его мудрость. По-казахски это «халық даналығы», по-английски — wisdom of the people.": "Нахшилар һәр дәвирдә хәлқниң һаяти вә даналиғини ипадилигән. Қазақчә бу «халық даналығы», инглизчә — wisdom of the people.",
"Песни о природе": "Тәбиәт һәққидики нахшилар",
"Кочуя по степи, казахи воспевали природу и сравнивали её величие с храбростью и мужеством предков. Они слушали сказания (эпос, жыр) под звуки кобыза или домбры.": "Далада көчүп жүргән қазақлар тәбиәтни мәдһийилигән вә униң улуғлуғини ата-бовилириниң батурлуғи вә мәрдлиги билән селиштурған. Улар қобуз яки домбира авазиға қошулуп дастанларни (эпос, жыр) аңлиған.",
"Жырау": "Жырау",
"Жырау — высокопоставленный человек: мог быть предводителем племён, полководцем, важным сановником. Его главная задача — служить государству, хану и народу.": "Жырау — жуқури мәртивилик адәм: қәбилиләрниң йетәкчиси, сәркәрдә, муһим әмәлдар болалиған. Униң асаслиқ вәзиписи — дөләткә, хан вә хәлққә хизмәт қилиш.",
"Акын": "Ақин",
"Акын — вольный человек, который занимался творчеством постоянно. Он создавал песни и на бытовые темы, пел о повседневных чувствах, его приглашали на семейные торжества.": "Ақин — әркин адәм, у һемишә ижад билән шуғуллинатти. У күндилик турмуш темилирида нахшиларни яратти, күндилик һис-туйғулар һәққидә ейтти, уни аилилик тәнтәнилиргә тәклип қилатти.",
"Жаяу Муса и «Ақ сиса»": "Жаяу Муса вә «Ақ сиса»",
"Жаяу Муса (Муса Байжанулы, 1835–1929) — казахский народный композитор и акын. Его самая знаменитая песня «Ақ сиса» осуждает подлые поступки богачей.": "Жаяу Муса (Муса Байжанұлы, 1835–1929) — қазақниң хәлқ композитори вә ақини. Униң әң мәшһур «Ақ сиса» нахшиси байларниң пәс қилмишлирини әйибләйду.",
"Жырау или акын?": "Жырау яки ақин?",
