"Верно. Так песни передавали мудрость народа.": "Тоғра. Шуниң билән нахшилар хәлқниң даналиғини йәткүзгән.",
"Неверно. Жырау служили государству, хану и народу.": "Хата. Жыраулар дөләткә, хан вә хәлққә хизмәт қилған.",
