"Неверно. Они сочиняли и на бытовые темы.": "Хата. Улар күндилик турмуш темилирида һәм ижад қилған.",
"Неверно. Это относится к жырау; акыны были вольными людьми.": "Хата. Бу жыраулар һәққидә; ақинлар әркин адәмләр еди.",
"Верно. Он жил с 1835 по 1929 год.": "Тоғра. У 1835-жилдин 1929-жилғичә яшиған.",
"Неверно. Он прекрасно владел кобызом, домброй, скрипкой и сырнаем.": "Хата. У қобуз, домбира, скрипка вә сурнайда әла чалатти.",
"Верно. Богач отобрал у Мусы единственного хорошего коня.": "Тоғра. Бай Мусадин бирдинбир яхши атни тартивалған.",
