"Объяснять, кто такие сал и сері, и называть знаменитых композиторов Биржан-сала и Ахана сері.": "Сал вә серини кимләр екәнлигини чүшәндүрүш вә мәшһур композиторлар Биржан-сал билән Ахан серини аташ.",
"Сал и сері": "Сал вә сері",
"Сал и сері — представители древней поэтической культуры. Их творчество — своеобразная часть культурного наследия Казахстана.": "Сал вә сері — қедимки шеирийәт мәдәнийитиниң вәкиллири. Уларниң ижади Қазақстанниң мәдәнийәт мирасиниң алаһидә бир қисми.",
"Радость и воспитание": "Хошаллиқ вә тәрбийә",
"Сал и сері представляли интересы молодёжи и развлекали её. Но они ещё и воспитывали: учили основам степного этикета и правилам поведения.": "Сал вә сері яшларниң мәнпәтини қоғдиди вә уларни хушал қилди. Лекин улар йәнә тәрбийиләтти: даланиң әдәп-әхлақ асаслирини вә қилиқ қаидилирини үгәттитти.",
"Биржан-сал": "Биржан-сал",
"Биржан-сал Кожагулулы (1834–1897) — казахский акын и народно-профессиональный певец-композитор. Он известен благодаря айтысу с Сарой Тастанбек-кызы.": "Биржан-сал Қожағұлұлы (1834–1897) — қазақ ақини вә хәлқ кәспий нахшичи-композитор. У Сара Тастанбекқизи билән айтисқа қатнашқанлиғи билән мәшһур.",
"Ахан сері": "Ахан сері",
"Ахан сері Корамсаулы (1843–1913) — народный поэт-акын, певец и композитор. Слово «сері» значит «поэт-песенник».": "Ахан сері Қорамсаұлы (1843–1913) — хәлқ шаири-ақин, нахшичи вә композитор. «Сері» сөзи «нахша шаири» дегән мәна.",
"Чем отличаются": "Пәрқи немидә",
"Сал — певец-композитор и импровизатор, особо талантливый человек. Сері тоже певец и импровизатор, но ещё и прекрасный охотник, умеющий тренировать ловчих птиц.": "Сал — нахшичи-композитор вә импровизатор, алаһидә қабилийәтлик адәм. Сері дә нахшичи вә импровизатор, лекин у йәнә әла овчи болуп, овчи қушларни үгитишни билиду.",
"Разложи: сал, сері или оба": "Тәртипкә селиң: сал, сері яки иккиси",
"Реши, к кому относится каждая карточка.": "Һәр бир карточка кимгә мунасивәтлик екәнлигини һәл қилиң.",
