"Урок 11. Память народа": "11-дәрис. Хәлқниң хатирә",
"Память народа": "Хәлқниң хатирә",
"Объяснять, что такое культурное наследие и пение a cappella, и называть, что создал Абай Кунанбаев.": "Мәдәний мирас вә a cappella нахша ейтишниң немә екәнлигини чүшәндүрүш вә Абай Құнанбаев немә яратқанлиғини аташ.",
"Культурное наследие": "Мәдәний мирас",
"Наследие — это то, что народ бережно хранит и передаёт из поколения в поколение. По-казахски — ата мұра, по-английски — heritage.": "Мирас — хәлқ уни авайлап сақлап, әвладтин әвладқа қалдуридиған нәрсә. Қазақчә — ата мұра, инглизчә — heritage.",
"Абай Кунанбаев": "Абай Құнанбаев",
"Абай (1845–1904) — казахский поэт, композитор и мыслитель, основоположник казахской письменной литературы. Его песни народ хранит как великое сокровище.": "Абай (1845–1904) — қазақ шаири, композитор вә мутәпәккүри, қазақ йезиқ әдәбиятиниң асасчиси. Униң нахшилирини хәлқ улуқ хәзинә сүпитидә сақлайду.",
"Имя Абай": "Абай еси",
"Настоящее имя — Ибрагим. Прозвище Абай дала ему бабушка Зере, оно означает «внимательный», «осторожный» и осталось с ним на всю жизнь.": "Һәқиқий еси — Ибраһим. Абай ләқимини униңға чоң аниси Зере қойған, у «диққәтлик», «еһтиятчан» дегән мәна беридиған болуп, пүтүн өмри униңға һәмраһ болған.",
"Пение a cappella": "A cappella нахша ейтиш",
"A cappella — это пение без инструментального сопровождения. Звучат только голоса. Сравни: одну и ту же песню можно услышать с аккомпанементом и без него.": "A cappella — қурал һәмраһлиғисиз нахша ейтиш. Пәқәт аваз аңлиниду. Селиштуруп көрүң: бир нахшини һәмраһлиқ билән вә һәмраһлиқсиз аңлиғили болиду.",
"Песня, ставшая народной": "Хәлқниң нахшисиға айланған нахша",
"Гёте написал «Ночную песню странника», Лермонтов переложил её на русский язык, а спустя полвека Абай передал её содержание на казахском. Так появилась песня «Қараңғы түнде тау қалғып».": "Гёте «Саяһәтчиниң кечилик нахшиси»ни язған, Лермонтов уни русчиға тәрҗимә қилған, йерим әсирдин кейин Абай униң мәзмунини қазақчә йәткүзгән. Шундақ қилип «Қараңғы түнде тау қалғып» нахшиси пәйда болған.",
