"Музыкальные произведения Абая — часть культурного наследия не только казахского народа, но и всего мира.": "Абайниң музикилиқ әсәрлири пәқәт қазақ хәлқиниң әмәс, пүтүн дуняниң мәдәний мирасиниң бир қисми.",
"Лермонтов переложил стихотворение Гёте на казахский язык.": "Лермонтов Гётениң шеирини қазақчиға тәрҗимә қилған.",
