"Абай считается основоположником казахской письменной литературы.": "Абай қазақ йезиқ әдәбиятиниң асасчиси һесаплиниду.",
"Это годы жизни Абая.": "Бу Абайниң яшиған жиллири.",
"Настоящее имя — Ибрагим, а Зере звали бабушку.": "Һәқиқий еси — Ибраһим, Зере болса чоң анисиниң еси.",
"Они передаются от отца к сыну.": "Улар атидин оғулға өтиду.",
