"Домбра была бессменным спутником акынов, жырау и жыршы. Это главный инструмент народных кюев.": "Домбира ақинлар, жыраулар вә жыршиларниң алмас һәмраһи болған. Бу — хәлқ күйлириниң асаслиқ қураллири.",
"Кюй": "Күй",
"Большинство известных кюев написаны именно для домбры. Их создали наши предки.": "Мәшһур күйләрниң көпчилики дәл домбираға яратқан. Уларни бизниң ата-бовилиримиз яратқан.",
"Современные композиторы не только сохраняют музыку предков, но и создают новую. Они берут всё лучшее из музыкального наследия народа.": "Һазирқи заман композиторлири ата-бовилар музикисини сақлап қалмастин, йеңисини һәм яратиду. Улар хәлқниң музикилиқ мирасидики әң яхшисини елиду.",
