"Чемпион республики": "Республика чемпиони",
"Он был Героем Труда Казахстана и народным артистом СССР.": "У Қазақстан Әмгәк Қәһримани вә СССР хәлқ артисти еди.",
"Как по-английски называется симфонический кюй?": "Симфонийилик күй инглизчә қандақ аталиду?",
"Английский термин — symphony kui.": "Инглизчә термин — symphony kui.",
"Домбра была бессменным спутником акынов, жырау и жыршы.": "Домбира ақинлар, жыраулар вә жыршиларниң алмас һәмраһи болған.",
"Большинство известных кюев написаны для скрипки.": "Мәшһур күйләрниң көпчилики скрипка үчүн яратқан.",
"Симфонический кюй — авторское сочинение современного композитора на основе народной музыки.": "Симфонийилик күй — һазирқи заман композиторниң хәлқ музикиси асасида яратқан муәллипләр әсири.",
"Симфонический кюй — это просто переложение народного кюя для оркестра.": "Симфонийилик күй — хәлқ күйиниң оркестрға жәңла көчүрүлмиси.",
"«Дайрабай» Е. Рахмадиева — первый симфонический кюй.": "Е. Рахмадиевниң «Дайрабай»и — тунҗи симфонийилик күй.",
"Е. Рахмадиев был композитором и педагогом.": "Е. Рахмадиев композитор вә педагог еди.",
"Е. Рахмадиев 27 лет возглавлял Государственную консерваторию.": "Е. Рахмадиев Дөләт консерваториясини 27 жил башқурған.",
"Современные композиторы только сохраняют старую музыку и ничего нового не создают.": "Һазирқи заман композиторлири пәқәт қедимки музикини сақлайду, йеңи һеч нәрсә яратмайду.",
"Песню «Мечта детства» написал Е. Рахмадиев.": "«Балилиқ арман» нахшисини Е. Рахмадиев язған.",
"Симфонический кюй создан для звучания оркестра.": "Симфонийилик күй оркестр аваз беришигә яритилған.",
"Это верно: домбра сопровождала народных певцов и сказителей.": "Бу тоғра: домбира хәлқ нахшичилири вә дастанчилириға һәмраһ болған.",
"Большинство известных кюев написаны для домбры.": "Мәшһур күйләрниң көпчилики домбираға яратқан.",
"Композитор опирается на фольклорный первоисточник.": "Композитор фолклорлуқ асасқа таянған.",
"Это не просто переложение, а новое авторское сочинение.": "Бу жәңла көчүрмә әмәс, йеңи муәллипләр әсири.",
"Так говорят о нём музыковеды.": "Музыкашунаслар у һәққидә шундақ дәйду.",
"Ещё он был общественным и политическим деятелем.": "У йәнә җәмийәт вә сиясәт әрбаби еди.",
"Консерваторию он возглавлял восемь лет, а 27 лет был председателем Союза композиторов Казахстана.": "У консерваторияни сәккиз жил башқурған, 27 жил Қазақстан Композиторлар иттипақиниң рәиси болған.",
"Они и сохраняют музыку предков, и создают новую.": "Улар ата-бовилар музикисини сақлайду һәм йеңисини яритиду.",
"Автор песни — Е. Обухова.": "Нахшиниң автори — Е. Обухова.",
"Его сочиняют с оркестровкой, поэтому звучит оркестр.": "Уни оркестровка билән яритиду, шуңа оркестр аңлиниду.",
"Верно. Это верно: домбра сопровождала народных певцов и сказителей.": "Тоғра. Бу тоғра: домбира хәлқ нахшичилири вә дастанчилириға һәмраһ болған.",
"Неверно. Большинство известных кюев написаны для домбры.": "Хата. Мәшһур күйләрниң көпчилики домбираға яратқан.",
"Верно. Композитор опирается на фольклорный первоисточник.": "Тоғра. Композитор фолклорлуқ асасқа таянған.",
"Неверно. Это не просто переложение, а новое авторское сочинение.": "Хата. Бу жәңла көчүрмә әмәс, йеңи муәллипләр әсири.",
"Верно. Так говорят о нём музыковеды.": "Тоғра. Музыкашунаслар у һәққидә шундақ дәйду.",
"Верно. Ещё он был общественным и политическим деятелем.": "Тоғра. У йәнә җәмийәт вә сиясәт әрбаби еди.",
"Неверно. Консерваторию он возглавлял восемь лет, а 27 лет был председателем Союза композиторов Казахстана.": "Хата. У консерваторияни сәккиз жил башқурған, 27 жил Қазақстан Композиторлар иттипақиниң рәиси болған.",
"Неверно. Они и сохраняют музыку предков, и создают новую.": "Хата. Улар ата-бовилар музикисини сақлайду һәм йеңисини яритиду.",
"Неверно. Автор песни — Е. Обухова.": "Хата. Нахшиниң автори — Е. Обухова.",
"Верно. Его сочиняют с оркестровкой, поэтому звучит оркестр.": "Тоғра. Уни оркестровка билән яритиду, шуңа оркестр аңлиниду.",
