"Урок 13. Музыкальные вариации": "13-дәрис. Музикилиқ вариацийәләр",
"Музыкальные вариации": "Музикилиқ вариацийәләр",
"Объяснять, что такое вариация, и различать профессии композитора и аранжировщика.": "Вариацийә дегәнниң немә екәнлигини чүшәндүрүш вә композитор билән аранжировкичиниң кәспини пәриқләндүрүш.",
"Композитор сочиняет музыку: придумывает образы, развивает и дополняет их. Он пишет и для голоса, и для инструментов.": "Композитор музика ижад қилиду: образларни ойлап чиқиду, уларни риважландуриду вә толуқлайду. У авазму, қураллармы үчүн йезиду.",
"Что пишет композитор": "Композитор немә йезиду",
"Композиторы создают разные произведения: от оперы до популярных песен. Они сочиняют вступление, главный мотив и завершение.": "Композиторлар һәр хил әсәрләрни яратиду: операдин тартип машһур нахшиларғичә. Улар кириш қисимни, асасий мотивни вә хатимини ижад қилиду.",
"Аранжировщик": "Аранжировкичи",
"Аранжировщик «оформляет» музыкальные композиции. Он перекладывает музыку под нужные инструменты или голос.": "Аранжировкичи музикилиқ композицийәләрни «рәсмийләштүриду». У музикини керәклик қураллар яки аваз үчүн қайта ишләйду.",
"Где нужен аранжировщик": "Аранжировкичи қәйәрдә керәк",
"Эта профессия востребована в шоу-бизнесе, индустрии развлечений и кино. Для работы аранжировщики используют специальные программы, которые воспроизводят звучание разных инструментов.": "Бу кәсип шоу-бизнесда, көңүл ечиш саһәсидә вә киноға еһтияҗлиқ. Ишлиши үчүн аранжировкичилар һәр хил қураллариң авазини чиқиридуған алаһидә программилардин пайдилиниду.",
"Вариация": "Вариацийә",
"Мелодия видоизменяется, но не теряет своих характерных очертаний. Такой приём в музыке называется вариация.": "Мәлодийә өзгириду, лекин өзиниң хас сизиқлирини йоқатмайду. Музикида мундақ усул вариацийә дәп атилиду.",
"Композитор или аранжировщик?": "Композиторму яки аранжировкичиму?",
"Определи, кто чем занимается: композитор или аранжировщик.": "Ким немә билән шуғуллиниду, шуни бәлгиләң: композиторму яки аранжировкичиму.",
"Чья это работа?": "Бу кимниң иши?",
"Сочиняет музыку": "Музика ижад қилиду",
"Он придумывает музыку с нуля.": "У музикини нөлдин ойлап чиқиду.",
"Придумывает основной мотив произведения": "Әсәрниң асасий мотивини ойлап чиқиду",
"Это начало новой музыки.": "Бу йеңи музикиниң бешиси.",
