"Голоса и подголоски": "Аваз вә йөләк авазлар",
"Объяснять, что такое многоголосие, подголосок и тембр, и называть правила бережного отношения к голосу.": "Көп авазлиқ, йөләк аваз вә тембр дегәнләрниң немә екәнлигини чүшәндүрүш вә авазни есил сақлаш қаидилирини атап бериш.",
"Многоголосие": "Көп авазлиқ",
"Когда поют сразу несколько голосов, получается многоголосие. Его ещё называют полифонией (по-казахски «көпдауысты», по-английски polyphony).": "Бирнәччә аваз бирла вақитта ейтилғанда көп авазлиқ пәйда болиду. Уни йәнә полифонийә дәпму атайду (қазақчә «көпдауысты», инглизчә polyphony).",
"Голос неповторим": "Аваз тәкрарланмас",
"Голос каждого человека звучит по-своему. Один голос низкий и сильный, другой тёплый и средний, третий высокий и лёгкий.": "Һәр бир адәмниң авази өзичә яңрайду. Бир аваз пәс вә күчлүк, йәнә бири илиқ вә оттура, учинчиси егиз вә йеңил.",
"Подголосок": "Йөләк аваз",
"Голос, который вторит основному голосу, то есть главной мелодии, называют подголоском. Он добавляет хору дополнительные краски.": "Асасий авазни, йәни баш мәлодийәни тәкрарлайдиған авазни йөләк аваз дәп атайду. У хорға қошумчә рәңләрни қошиду.",
"Тембр": "Тембр",
"Индивидуальную окраску и яркость голоса называют тембром. Бывает тембр резкий и мягкий, грудной, головной и смешанный.": "Авазниң алаһидә рәңги билән ярқинлиғини тембр дәп атайду. Тембр өткүр вә йумшақ, көкрәк, баш вә арилаш болиду.",
"Береги голос": "Авазиңни сақла",
"Голос — уникальный инструмент. Не кричи и не шепчи, пей воду комнатной температуры, а перед пением не пей апельсиновый сок и молочные напитки.": "Аваз — бетәкрар қурал. Қичқирима вә пичирлима, хона һароратидики су ичкин, нахша ейтиштин илгири апельсин шербити вә сүт ичимликлирини ичмигин.",
