"Самый главный музыкант": "Әң муһим музикант",
"Объяснять, какая задача стоит перед дирижёром и почему его называют «главным» музыкантом.": "Дирижёрниң алдида қандақ вәзипә туридиғанлиғини вә немишқа уни «әң муһим» музикант дәп атайдиғанлиғини чүшәндүрүш.",
"Кто такой дирижёр": "Дирижёр ким",
"Дирижёр управляет хором или оркестром. Его называют самым главным музыкантом в команде музыкантов.": "Дирижёр хор яки оркестрни башқуриду. Уни музикантлар командисидики әң муһим музикант дәп атайду.",
"Хор и оркестр — команда": "Хор вә оркестр — команда",
