"Главная задача дирижёра": "Дирижёрниң асасий вәзиписи",
"Дирижёр должен увлечь музыкантов и повести их за собой. От его мастерства зависит, как звучит хор или оркестр.": "Дирижёр музикантларни қизиқтуруп, уларни өзи билән елип маңиши керәк. Хор яки оркестрниң қандақ яңришиси униң маһарәтлигигә бағлиқ.",
"Дирижёрская палочка": "Дирижёр таяқчиси",
"Достаточно взмаха дирижёрской палочки — и музыканты становятся единым целым. Они чувствуют даже малейшие нюансы настроения дирижёра.": "Дирижёр таяқчисини бир силкиш йетәрлик — музикантлар бир пүтүн болуп қалиду. Улар дирижёрниң кәйпиятидики әң кичик нюансларниму һес қилиду.",
"Песня «Атамекен»": "«Атамекен» нахшиси",
"Музыку к песне «Атамекен» написал Е. Хасангалиев, слова — К. Мырзалиев. Эта песня часто звучит и в вокальной, и в инструментальной обработках.": "«Атамекен» нахшисиниң музикисини Е. Хасангалиев, сөзини К. Мырзалиев йезиған. Бу нахша авазлиқму, қураллиқму ишләнмиләрдә көп яңрайду.",
"Кто что делает?": "Ким немә қилиду?",
"Разложи карточки: что относится к дирижёру, к хору, а что к оркестру.": "Карточкиларни тәртипкә қоюң: немә дирижёрға, немә хорға, немә оркестрға мансуп.",
