"Урок 16. Мастерская праздника": "16-дәрис. Байрам устиханиси",
"Мастерская праздника": "Байрам устиханиси",
"Объяснять, что такое канон, и узнавать, как он исполняется.": "Канон дегәнниң немә екәнлигини чүшәндүрүш вә униң қандақ орунлинидиғанлиғини билиш.",
"Что такое канон": "Канон дегән немә",
"Канон — это музыкальное произведение, в котором голоса вступают не одновременно, а один за другим. Опоздание здесь — главная «изюминка».": "Канон — авазлар бирла вақитта әмәс, бири-биридин кейин киридиған музикилиқ әсәр. Бу йәрдә кечикиш — әң муһим «алаһидилик».",
"Опоздание в музыке": "Музикида кечикиш",
"В жизни опаздывать на урок плохо. А в каноне «опоздание» голосов — это красиво и задумано композитором.": "Һаятта дәрискә кечикиш яхши әмәс. Канонда болса авазларниң «кечикиши» гөзәл вә композитор тәрипидин ойлаштурулған.",
"Самый известный канон": "Әң тонулған канон",
"Самый известный пример канона — французская песенка «Братец Яков». Её можно петь и на других языках, например на английском.": "Канонниң әң тонулған мисали — франсузчә «Яков ака» нахшиси. Уни башқа тиллардиму, мәсилән инглиз тилидиму ейтишқа болиду.",
"Шанкобыз и варган": "Шанкобыз вә варган",
"Канон можно исполнять и на музыкальных инструментах. Шанкобыз и варган — родственные инструменты, но варган — это не шанкобыз, а его ближайший родственник.": "Канонни музикилиқ қураллардидиму орунлашқа болиду. Шанкобыз билән варган — туққан қураллар, лекин варган шанкобыз әмәс, бәлки униң әң йеқин туғқини.",
"Роли на празднике": "Байрамдики ролләр",
"Чтобы подготовить выступление на новогоднем празднике, нужно выбрать роль: дирижёр, певец или музыкант, играющий на инструменте. Ещё важно продумать исполнительский план.": "Йеңи жил байримида чиқиш тәйярлаш үчүн роль талләш керәк: дирижёр, нахшичи яки қураллада чалидиған музикант. Йәнә орунлаш пилани һәққидә ойлишиш муһим.",
"Выбери роль на празднике": "Байрамда ролни талла",
"Подумай, чем занимается каждый участник выступления, и разложи карточки по ролям.": "Һәр бир қатнашқучиниң немә билән шуғуллинидиғанлиғини ойлаң вә карточкиларни ролләр бойичә тәртипкә қоюң.",
"Какая это роль?": "Бу қандақ роль?",
"Музыкант на инструменте": "Қураллада чалидиған музикант",
"Управляет исполнением": "Орунлашни башқуриду",
"Он руководит всеми участниками.": "У барлиқ қатнашқучиларға рәһбәрлик қилиду.",
"Показывает, когда должен вступить каждый голос": "Һәр бир авазниң қачан киришини көрситиду",
"Он подаёт знаки исполнителям.": "У орунлиғучиларға ишарәт бериду.",
"Стоит перед исполнителями и ведёт их за собой": "Орунлиғучиларниң алдида туруп, уларни өзи билән елип маңиду",
"Он не поёт и не играет, а направляет.": "У нахша ейтмайду вә чалмайду, бәлки йол көрситиду.",
