"Евгений Шварц написал «Сказку о потерянном времени».": "Евгений Шварц «Йоқап кәткән вақит һәққидики чөчәк»ни йезиған.",
"Петя Зубов — ученик пятого класса.": "Петя Зубов — бәшинчи синип оқуғучиси.",
"Варган и шанкобыз — один и тот же инструмент.": "Варган вә шанкобыз — бир қурал.",
"Для выступления можно выбрать роль дирижёра.": "Чиқиш үчүн дирижёр ролини талләшкә болиду.",
"Исполнительский план нужен только дирижёру и не нужен остальным.": "Орунлаш пилани пәқәт дирижёргә керәк, башқиларға керәк әмәс.",
"Нет: голоса вступают один за другим.": "Яқ: авазлар бири-биридин кейин кириду.",
"Так и есть, опоздание — это задумка произведения.": "Шундақ, кечикиш — әсәрниң ойлиши.",
