"Верно. Это автор сказки.": "Тоғра. Бу чөчәкниң автори.",
"Неверно. Петя Зубов — третьеклассник.": "Хата. Петя Зубов — үчинчи синип оқуғучиси.",
"Верно. Они родственные инструменты, но это разные инструменты.": "Тоғра. Улар туққан қураллар, лекин бу һәр хил қураллар.",
"Неверно. Варган — не шанкобыз, а его ближайший родственник.": "Хата. Варган — шанкобыз әмәс, бәлки униң әң йеқин туғқини.",
