"9-сабақ. Домбыра — асыл мұра": "9-дәрис. Домбира — қиммәтлик мирас",
"Домбыра — асыл мұра": "Домбира — қиммәтлик мирас",
"Мәдениет пен мәдени мұра деген не екенін түсіндіру, «Ақсақ құлан» күйінің мазмұнын айту және домбыраның құрметті орнын білу.": "Мәдәнийәт вә мәдәний мирас дегән немә екәнлигини чүшәндүрүш, «Ақсақ құлан» күйиниң мәзмунини ейтип бериш вә домбираниң һөрмәтлик орнини билиш.",
"Мәдениет деген не?": "Мәдәнийәт дегән немә?",
"Адамзаттың ақыл-ойымен және қолымен жасалған құндылықтардың бәрі мәдениет деп аталады. Мысалы: әдебиет, қолөнер, бейнелеу өнері, сәулет өнері және музыка.": "Адәмзатниң әқил-идрики вә қоли билән яритилған барлиқ қиммәтликләр мәдәнийәт дәп атилиду. Мәсилән: әдәбийат, қол һүнәрвәнчилики, тәсвирий сәнәт, меъмарчилиқ сәнити вә музика.",
"Мәдени мұра": "Мәдәний мирас",
"Осы өнерлердің барлық туындылары ата-бабамыздан келе жатқан мәдени мұраға жатады. Домбыра мен күй де — біздің асыл мұрамыз.": "Бу сәнәтләрниң барлиқ әсәрлири ата-бовилиримиздин қалған мәдәний мирасқа мансуп. Домбира вә күй — бизниң қиммәтлик мирасимиз.",
"«Ақсақ құлан» күйі": "«Ақсақ құлан» күйи",
"Бұл — қазақтың халық күйі, аңыз күй. Ол халық арасына кең таралған асыл мұрамыздың бірі.": "Бу — қазақниң хәлқ күйи, әпсанилик күй. У хәлқ арисида кәң тарқалған қиммәтлик мирасимизниң бири.",
"Күйдің аңызы": "Күйниң әпсаниси",
"Аңшылыққа шыққан хан баласы қайтыс болады. Хан қайғылы хабарды айтқан адамның көмейіне қорғасын құймақ болады. Сонда бір қарт домбырашы күймен хабарды жеткізеді.": "Ов овлашқа чиққан хан оғли өлиду. Хан қайғулуқ хәвәрни ейтқан адәмниң тамиғиға қоғошун қуймақчи болиду. Шу чағда бир қери домбирачи хәвәрни күй арқилиқ йәткүзиду.",
"Домбыраға құрмет": "Домбираға һөрмәт",
"2018 жылдан бастап шілде айының бірінші жексенбісі — «Домбыра күні» мерекесі. 2014 жылы ЮНЕСКО шешімімен домбырамен орындалатын күй өнері адамзаттың бүкіләлемдік құндылықтарына енді.": "2018-жилдин башлап июльниң биринчи йәкшәнбиси — «Домбира күни» байрими. 2014-жили ЮНЕСКОниң қарари билән домбира билән орунлинидиған күй сәнити адәмзатниң пүтүн дунья қиммәтликлиригә киргүзүлди.",
"Күй мен әнді ажырат": "Күй билән нахшини айрип бил",
"Әр карточканы дұрыс топқа қой: «Ақсақ құлан» күйіне ме, әлде «Домбыра болып сөйледім» әніне ме?": "Һәр бир карточкини тоғра топқа қой: «Ақсақ құлан» күйигә яки «Домбыра болып сөйледім» нахшисиға?",
"Қайсысына қатысты?": "Қайсисиға мунасивәтлик?",
