"Қобыз аспабының жасалуын сипаттау, Қорқыт ата мен Ықылас Дүкенұлы туралы айту.": "Қобуз қурализиниң ясилишини тәсвирләш, Қорқыт ата вә Ықылас Дүкенұлы һәққидә ейтип бериш.",
"Қобыз – көне аспап": "Қобуз — қедимки қурал",
"Қобыз – ұлттық мәдени мұрамыздағы ерекше орны бар аспап. Оны скрипка, виолончель сияқты еуропалық ыспалы аспаптардың арғы атасы деп санайды.": "Қобуз — миллий мәдәний мирасимиздә алаһидә орни бар қурал. Уни скрипка, виолончель охшаш явропалиқ яй билән чилинидиған қураллариң қедимки бовиси дәп һесаплайду.",
"Қобыздың жасалуы": "Қобузниң ясилиши",
"Шеберлер қобыздың жасалуына аса зор мән берген. Шанақты ағаштан ойып, үңгіп жасайды, ал оның бетіне көн қаптайды.": "Устилар қобузниң ясилишиға интайин зор әһмийәт бәргән. Шанақни яғачтин ойуп, ковлап ясайду, униң бетигә тери қаплайду.",
"Қорқыт ата": "Қорқыт ата",
"Қобыз аспабы Қорқыт ата есімімен қатар аталады. Ол – ел бірлігін нығайтқан кемеңгер қайраткер, ғұлама ойшыл, күйші, жырау.": "Қобуз қуралиниң исми Қорқыт ата билән қатар атилиду. У — әл иттипақлиғини мустәһкәмлигән дана ғәйрәтчи, алим пәйласоп, күйчи, жырау.",
"ЮНЕСКО тізімінде": "ЮНЕСКО тизимликидә",
"Қорқыттың музыкалық мұрасы, эпосы және халық ақындары 2018 жылы ЮНЕСКО-ның мәдени мұралар тізіміне енгізілді.": "Қорқутниң музикилиқ мирасы, эпоси вә хәлқ шаирлири 2018-жили ЮНЕСКОниң мәдәний мирас тизимликигә киргүзүлди.",
"Ықылас Дүкенұлы": "Ықылас Дүкенұлы",
"Ықылас Дүкенұлы (1843–1916) – композитор, күйші, қобызшы. Ол Жезқазған өңірінде дүниеге келген, қобыз өнерін заманымызға жеткізген ұлы күйші.": "Ықылас Дүкенұлы (1843–1916) — композитор, күйчи, қобузчи. У Жезқазған өлкисидә туғулған, қобуз сәнитини бүгүнки күнгә йәткүзгән бөюк күйчи.",
