"Атадан қалған жауһар жыр": "Атидин қалған гөһәр жир",
"Жыр, жырау, жыршы ұғымдарын түсіндіру және жыр батырлары мен Бұқар жырауды атау": "Жир, жырау, жыршы чүшәнчилирини чүшәндүрүш вә жир батурлири билән Бұқар жырауни атап бериш",
"Жыр деген не?": "Жир дегән немә?",
"Халық өмірінен алынған оқиғалы, ұзақ өлеңдерді «жыр» деп атайды. Батырлар жыры көп халықта сақталған.": "Хәлқ һаятидин елинған вақиәлик, узун шеирларни «жир» дәп атайду. Батурлар жири көп хәлқләрдә сақланған.",
"Батырлар кім?": "Батурлар ким?",
"Ертеде халық елін-жерін қорғайтын, суға салса батпайтын, отқа салса жанбайтын хас батырларды аңсаған. Алпамыс, Қобыланды, Ер Тарғын, Қамбар сияқты батырлар осылай шыққан.": "Қедимда хәлқ өз әли-зәминини қоғдайдиған, сувға салсиму чөкмәйдиған, отқа салсиму көймәйдиған һәқиқий батурларни арзу қилған. Алпамыс, Қобыланды, Ер Тарғын, Қамбар охшаш батурлар шундақ келип чиққан.",
"Жыр қалай айтылады?": "Жир қандақ ейтилиду?",
"Батырлардың ерліктерін домбыраға, қобызға қосып айтқан. Кейде аспапсыз-ақ жыр, терме түрінде екпінді әуенмен баяндаған.": "Батурларниң баһадирлиқини домбираға, қобузға қошуп ейтқан. Баъзида қурал болмай, жир, терме шәклидә җанлиқ күй билән баян қилған.",
"Бір ұғым — үш атау": "Бир чүшәнчә — үч ат",
"Жырды гректер «эпос» дейді, қазақтар «жыр», ал қырғыздар «ыр» дейді. Қазақтың жыр-дастандары көбіне 7-8 буынмен жазылады.": "Жирни грекләр «эпос» дәйду, қазақлар «жыр», қирғизлар болса «ыр» дәйду. Қазақниң жир-дастанлири көпинчә 7-8 һеҗалиқ болуп йезилиду.",
