"«Майда қоңыр» және «Дүние» — Естайдың қазақ халқына белгілі әндері. «Құсни-Қорлан» әні бүкіл әлемге танымал.": "«Майда қоңыр» вә «Дүние» — Естайниң қазақ хәлқигә тонуш нахшилири. «Құсни-Қорлан» нахшиси пүтүн дунйаға тонуш.",
"«Құсни-Қорлан» әні": "«Құсни-Қорлан» нахшиси",
"Өлеңі мен әнін Естай жазған. Ән сұлулықты дәріптейді және қазақтың ең үздік әндерінің бірі.": "Шеири билән нахшисини Естай йезип чиққан. Нахша гөзәллиқни мәдһийиләйду вә қазақниң әң яхши нахшилириниң бири.",
"Ән қалай туды?": "Нахша қандақ туғулған?",
"Естай 20 жасында Маралды ауылындағы тойда Сұлтан бидің Құсни және Қорлан есімді қыздарын көріп, олардың сұлулығына таңғалып, есімдерін әнге қосқан.": "Естай 20 яшта Маралды йезисидики тойда Сұлтан бийниң Құсни вә Қорлан дегән қизлирини көрүп, уларниң гөзәллигигә һәйран қелип, исимлирини нахшиға қошқан.",
"«Қоғалы-ай» және сал, сері": "«Қоғалы-ай» вә сал, сери",
"«Қоғалы-ай» — ел арасына кең тараған қазақтың халық әні. Естай — Біржан сал мен Ақан серінің өнерін жалғастырушы ірі тұлға.": "«Қоғалы-ай» — әл арисида кәң тарқалған қазақниң хәлқ нахшиси. Естай — Біржан сал билән Ақан сериниң сәнитини давамлаштурғучи чоң шәхс.",
