"Симфониялық оркестрдің аспаптар топтарын ажырату және аспаптарды атау": "Симфониялик оркестрдики әсвап топлирини пәриқләндүрүш вә әсвапларни аташ",
"Симфониялық оркестр": "Симфониялик оркестр",
"Симфониялық оркестр алғаш рет 18-ғасырда Еуропада пайда болды. Оның құрамы ішекті-ысқышты, үрлемелі және соқпалы аспаптардан тұрады.": "Симфониялик оркестр тунҗи қетим 18-әсирдә Европада пәйда болған. Униң тәркивигә ысқақлиқ тарлиқ, пүвләш вә соқма әсваплар киридиу.",
"Ішекті-ысқышты және үрлемелі-ағаш": "Ысқақлиқ тарлиқ вә яғач пүвләш",
"Ішекті-ысқышты топқа скрипка, альт, виолончель, контрабас кіреді. Үрлемелі-ағаш топта флейта, гобой, кларнет, фагот бар.": "Ысқақлиқ тарлиқ топқа скрипка, альт, виолончель, контрабас киридиу. Яғач пүвләш топта флейта, гобой, кларнет, фагот бар.",
"Үрлемелі-мыс және шулы-ұрмалы": "Мис пүвләш вә шовқунлуқ-урма",
"Үрлемелі-мыс топқа валторна, труба, тромбон, туба жатады. Шулы-ұрмалы топта барабан, дауылпаз, үшбұрыш, тарелка, литавра, қоңырау, ксилофон сияқты аспаптар бар.": "Мис пүвләш топқа валторна, труба, тромбон, туба киридиу. Шовқунлуқ-урма топта барабан, дауылпаз, үчбуҗ, тарелка, литавра, қоңғурақ, ксилофон охшаш әсваплар бар.",
"Клавишті және қосымша топ": "Клавишлиқ вә қошумчә топ",
"Клавишті аспаптарға рояль, орган, клавесин, клавикорд жатады. Қосымша топқа арфа кіреді.": "Клавишлиқ әсвапларға рояль, орган, клавесин, клавикорд киридиу. Қошумчә топқа арфа киридиу.",
"«Сарыжайлау» күйі": "«Сарыжайлау» күйи",
"«Сарыжайлау» — Тәттімбеттің күйі. Оны симфониялық оркестр де, қазақ халық аспаптары оркестрі де орындай алады. Халық аспаптары оркестрінде қобыз, домбыра, сазсырнай, жетіген бар.": "«Сарыжайлау» — Тәттимбәтниң күйи. Уни симфониялик оркестрму, қазақ хәлиқ әсвави оркестримуму орунлиялайду. Хәлиқ әсвави оркестрида қобыз, домбыра, сазсырнай, жетіген бар.",
