"Мамандықтың бес түрін ажырату, мамандық таңдауға не керек екенін түсіндіру және «Мамандығым — мақтаным» әні туралы айту.": "Кәсипниң бәш түрини пәриқләндүрүш, кәсип таллашқа немә керәкликини чүшәндүрүш вә «Кәспим — ғурурум» нахшиси һәққидә сөзләш.",
"Бақыттың кілті": "Бәхитниң ачқучи",
"Адам бақытты болғысы келеді. Бақыттың бір кілті — өзіңе ұнайтын жақсы мамандық таңдау. Өз ісіне риза адам өмірде де бақытты сезінеді.": "Адәм бәхитлик болғиси келиду. Бәхитниң бир ачқучи — өзигә яқидиған яхши кәсип таллаш. Өз ишидин рази болған адәм һаятта бәхитлик һес қилиду.",
"Мамандықтың бес түрі": "Кәсипниң бәш түри",
"Ғалымдар барлық мамандықты бес түрге бөледі: «Адам — адам», «Адам — белгі жүйесі», «Адам — техника», «Адам — табиғат», «Адам — өнер».": "Алимлар барлиқ кәсипләрни бәш түргә бөлиду: «Адәм — адәм», «Адәм — бәлгү системиси», «Адәм — техника», «Адәм — тәбиәт», «Адәм — санәт».",
"Мамандық таңдағанда": "Кәсип таллиғанда",
"Сүйікті ісіңе айналу үшін шын ниет, қалау, қызығушылық, бейімділік және қабілет керек. Ата-ананың ақылы мен тәрбиенің де маңызы бар.": "Сөйүмлүк ишиңға айлиниши үчүн һәқиқий ният, халаш, қизиқиш, мойиллиқ вә қабилийәт керәк. Ата-аниниң мәслиһити билән тәрбийәниңму әһмийити бар.",
"Ән «Мамандығым — мақтаным»": "«Кәспим — ғурурум» нахшиси",
"Бұл әннің сөзін А. Асылбек жазған, әнін Н. Хинков-Айтбаева шығарған. Әнде құрылысшы, дәрігер, мұғалім, аспаз, жүргізуші туралы айтылады. Әр шумақтан кейін қайырма қайталанады.": "Бу нахшиниң сөзини А. Асылбек йезип, нахшисини Н. Хинков-Айтбаева ижад қилған. Нахшида қурулушчи, доктур, оқутқучи, ашпәз, һайдавчи һәққидә ейтилиду. Һәр бәйттин кейин нақарат қайтилиниду.",
"Бір жұмысқа — үш көзқарас": "Бир ишқа — үч хил қарашлар",
"Өте ерте заманда үш жұмысшы бір құрылыста жұмыс істеп жүрген. Үшеуіне де «Не істеп жатырсың?» деп сұрағанда, олар үш түрлі жауап берген. Адамдар өз еңбегіне әртүрлі қарайды.": "Жуда қәдимки заманда үч ишчи бир қурулушта ишләп жүргән. Үчигиму «Немә қиливатисән?» дәп сориғанда, улар үч хил җаваб бәргән. Адәмләр өз әмгигигә һәр хил қарайду.",
"Мамандықты тобына орналастыр": "Кәсипни топиға җайлаштур",
"Әр мамандықты қай топқа жататынын тап.": "Һәр бир кәсипниң қайси топқа мансуплуғини тап.",
