"Музыкант мамандығының түрлерін атау және олардың не істейтінін түсіндіру.": "Музикант кәспиниң түрлирини аташ вә уларниң немә қилидиғинини чүшәндүрүш.",
"Мамандық дегеніміз не?": "Кәсип дегән немә?",
"Мамандық — адамның еңбек әрекетінің, жұмысының негізгі түрі. Ол адамнан белгілі бір дайындықты, білім мен дағдыны талап етеді.": "Кәсип — адәмниң әмгәк паалийитиниң, ишиниң асасий түри. У адәмдин мәлум тәйярлиқни, билим вә маһарәтни тәләп қилиду.",
"Музыкант кім?": "Музикант ким?",
"Музыкант — музыка саласында жұмыс істейтін маман, кәсіби түрде музыкамен шұғылданады. Олар: композитор, дирижёр, әнші, аспапта орындаушы және т.б.": "Музикант — музика саһасида ишләйдиған мутәхәссис, музика билән кәспий шуғуллиниду. Улар: композитор, дирижёр, нахшичи, әсвапта орунлиғучи вә башқилар.",
"Ертедегі музыка мамандары": "Қәдимки музика мутәхәссислири",
"Ата-бабаларымыз мұраға қалдырған әндер мен күйлер, жыр-термелер бізге жетті. Оны жеткізгендер — халықтың өзі және кәсіби мамандар: сал-серілер, әншілер мен күйшілер, жыраулар.": "Ата-бовилиримиз мирас қалдурған нахшилар билән күйләр, жыр-термиләр бизгә йәтти. Уни йәткүзгәнләр — хәлиқниң өзи вә кәспий мутәхәссисләр: сал-сәриләр, нахшичилар билән күйчиләр, жыраулар.",
"Аспаптық музыка": "Әсвап музикиси",
"Аспаптық музыка — арнайы музыкалық аспаптарда орындауға арналған шығарма. Домбыра, қобыз, скрипка, флейта, пианино — осындай аспаптар.": "Әсвап музикиси — алаһидә музика әсвапларда орунлашқа мөлчәрләнгән әсәр. Домбыра, қобыз, скрипка, флейта, пианино — шундақ әсваплар.",
"Мамандығым туралы музыкалық әңгіме": "Кәспим һәққидики музикилиқ һекайә",
"Бұл шығарманың музыкасын Н. Хинков-Айтбаева жазған. Онда кішкентай Наргиздің музыкант болу арманы туралы айтылады: ол скрипканың әдемі дауысын естіп, қатты қызығады.": "Бу әсәрниң музикисини Н. Хинков-Айтбаева йезип. Униңда кичик Наргизниң музикант болуш арманы һәққидә ейтилиду: у скрипканиң гөзәл авазини аңлап, қаттиқ қизиқиду.",
"Қай аспапта ойнайды?": "Қайси әсвапта чилиду?",
"Музыкант мамандығын қазақтың халық аспабына немесе басқа аспапқа қарай топтастыр.": "Музикант кәспини қазақниң хәлиқ әсвавиға яки башқа әсвапқа қарап топла.",
