"Дұрыс. Дұрыс, мамандық — адамның жұмысының негізгі түрі.": "Тоғра. Тоғра, кәсип — адәмниң ишиниң асасий түри.",
"Бұрыс. Мамандық белгілі бір дайындықты, білім мен дағдыны талап етеді.": "Хата. Кәсип мәлум тәйярлиқни, билим вә маһарәтни тәләп қилиду.",
"Дұрыс. Олар музыка саласында жұмыс істейтін мамандар.": "Тоғра. Улар музика саһасида ишләйдиған мутәхәссисләр.",
"Дұрыс. Олар әндер мен жырларды халыққа жеткізген.": "Тоғра. Улар нахшилар билән жырларни хәлиққә йәткүзгән.",
"Бұрыс. Аспаптық музыка аспапта орындалады.": "Хата. Әсвап музикиси әсвапта орунлиниду.",
"Дұрыс. Бәрі де музыкалық аспаптар.": "Тоғра. Һәммиси музика әсваплири.",
"Бұрыс. Ол скрипканың дауысына қызығып, скрипкашы болуды армандады.": "Хата. У скрипканиң авазиға қизиқип, скрипкичи болушни арман қилди.",
"Дұрыс. Дұрыс, ол фортепиано сыныбына барды.": "Тоғра. Тоғра, у фортепиано синипиға барди.",
