"16-сабақ. Музыкант болғым келеді!": "16-дәрис. Музикант болғум келиду!",
"Музыкант болғым келеді!": "Музикант болғум келиду!",
"Музыкамен байланысты мамандықтарды (әнші, биші, домбырашы, композитор) атау және олардың не істейтінін түсіндіру.": "Музика билән бағлиқ кәсипләрни (нахшичи, уссулчи, домбирачи, композитор) аташ вә уларниң немә қилидиғинини чүшәндүрүш.",
"Музыкант": "Музикант",
"Музыкант — музыка саласында жұмыс істейтін маман. Әнші, домбырашы, композитор — музыкамен айналысатын мамандықтар.": "Музикант — музика саһасида ишләйдиған мутәхәссис. Нахшичи, домбирачи, композитор — музика билән шуғуллинидиған кәсипләр.",
"Әнші — әнмен шығылданатын музыкант, вокалдық музыканы орындаушы. Ол әнді дауыспен айтады.": "Нахшичи — нахша билән шуғуллинидиған музикант, вокал музикисини орунлиғучи. У нахшини аваз билән ейтиду.",
"Домбырашы — домбыра аспабында ойнайтын музыкант. Ол аспапта ойнап, өнерін көрсетеді.": "Домбирачи — домбыра әсвавида чилидиған музикант. У әсвапта чилип, санитини көрситиду.",
"Композитор — музыкалық шығармалардың авторы, музыканы шығаратын адам. Латын тілінде бұл сөз «құрастырушы» дегенді білдіреді.": "Композитор — музикилиқ әсәрләрниң автори, музика яритидиған адәм. Латин тилида бу сөз «түзгүчи» дегән мәнини билдүриду.",
"Мамандық туралы таныстырылым": "Кәсип һәққидә тонуштуруш",
"Мамандық туралы айтқанда жалпы түсінікті, мамандықтың маманға қоятын кәсіби талаптарын және осы мамандық иелерін таныстыруға болады. Мұны әнші, биші, домбырашы, композитор туралы жасауға болады.": "Кәсип һәққидә ейтқанда умумий чүшәнчини, кәсипниң мутәхәссискә қойидиған кәспий тәләплирини вә мошу кәсип егилирини тонуштурушқа болиду. Буни нахшичи, уссулчи, домбирачи, композитор һәққидә қилишқа болиду.",
